// The coupon-box pick eval dataset (evals/couponBoxPick.eval.ts): 58 real
// store pages, each as the page outline the extension sends to
// POST /api/extension/coupon-box-pick, labelled by hand, plus 7 probe carts
// (store shop.example.com, note "Probe") built to check how rewards, offers,
// verify-a-discount, plain-discount and Redeem controls are read; their
// outlines come from the extension's own outline code. 57 of the real pages
// are shopping carts or checkout steps; one (the first restaurant.com case)
// is a gift-code redeem page that is not a cart.
//
// An outline is accessibility-tree style, one node per line; interactive
// nodes carry the [n] index the pick answers with. Every digit in a label is
// already "#", there is no free page text, and every label keeps only the
// words on the extension's fixed shopping-UI word list (any other word, such
// as a name on a saved address, is dropped in the browser and never sent). A
// label left with no listed word is sent with no name at all. The word list
// is the one of 2026-10-17 (it keeps point(s), member(s), military,
// student(s), teacher(s), verify and verification): the probes and the 51
// pages captured before 2026-10-13 are built with it, and the six pages
// captured live on 2026-10-16 are as an extension with the earlier list sent
// them, so those six may lack one of those words.
//
// Labels per case:
//   inputs    — every [n] that is the coupon / promo / discount code field
//               (any one of them is a correct pick);
//   toggles   — every [n] that reveals a hidden box ("Have a promo code?");
//   buttons   — when set, every [n] that applies the code typed into the
//               labelled input: a pick that names an input must then name
//               one of them as its button. Unset, the button is not scored.
//   knownMiss — set on a case the pick is known to get wrong, with why. It
//               still runs and is reported, but outside the pass rate.
// Inputs and toggles both empty = the page has no coupon box (an empty cart,
// a 404, a checkout step before the promo field, a code already applied); the
// only correct answer there is no pick at all. 19 cases are like that.
//
// Each case is a fixed snapshot scored against its own labels; a later store
// redesign does not invalidate it.

export interface CouponBoxCase {
    store: string
    outline: string
    inputs: number[]
    toggles: number[]
    buttons?: number[]
    knownMiss?: string
    note: string
}

